// Zeigt die aktive Konfiguration im Debug-Fenster (Schlüssel maskiert)
const cfg = JSON.parse(JSON.stringify(global.get('cfg')));
if (cfg.apis.orsKey) cfg.apis.orsKey = cfg.apis.orsKey.slice(0, 4) + '…';
msg.payload = cfg;
return msg;

initialize:
// ============================================================
//  MadridMove – zentrale Konfiguration
//  Alle externen APIs und alle Schwellwerte stehen NUR hier.
//  Jeder Wert kann per Umgebungsvariable überschrieben werden,
//  z. B. ORS_API_KEY=abc node-red   bzw.   docker run -e ORS_API_KEY=abc ...
// ============================================================
const cfg = {
    // Topic-Präfix: wird von configure.py gesetzt, nicht von Hand ändern
    prefix: 'upm-dsiot-g6/move',

    apis: {
        // BiciMAD (GBFS-Einstiegsdatei; die Feed-URLs werden daraus gelesen)
        gbfs: env.get('GBFS_URL') || 'https://madrid.publicbikesystem.net/customer/gbfs/v2/gbfs.json',
        // Open-Meteo (Wetter, ohne Schlüssel)
        meteo: env.get('METEO_URL') || 'https://api.open-meteo.com/v1/forecast',
        // openrouteservice (Routing mit Höhe und Wegart, kostenloser Schlüssel)
        ors: env.get('ORS_URL') || 'https://api.openrouteservice.org',
        orsKey: env.get('ORS_API_KEY') || '',
        // Geocoding (Adresse -> Koordinaten): Nominatim / OpenStreetMap, ohne Schlüssel.
        // Nutzungsregeln: max. 1 Anfrage pro Sekunde, Anwendung im User-Agent nennen.
        geocode: env.get('GEOCODE_URL') || 'https://nominatim.openstreetmap.org/search',
        geocodeUserAgent: 'MadridMove/1.0 (UPM DSIoT student project)'
    },

    // Suchgebiet für Adressen: Stadt Madrid (links, oben, rechts, unten)
    cityViewbox: '-3.89,40.57,-3.52,40.31',

    // Wetterpunkt: Puerta del Sol
    weatherPoint: { lat: 40.4168, lon: -3.7038 },

    // Parameter der Empfehlungslogik (Minuten, km/h, mm, °C)
    reco: {
        bikeMinBikes: 1,        // mind. so viele Räder am Start
        bikeMinDocks: 1,        // mind. so viele freie Plätze am Ziel
        dockMin: 2,             // Ausleihen + Abstellen
        minPerHmUp: 0.15,       // Aufschlag pro Höhenmeter bergauf (9 s)
        cyclewayBonusMax: 3,    // Bonus bei 100 % Radweg
        rainLight: 0.1,         // mm Niederschlag (letzte 15 min) = leichter Regen
        rainHeavy: 1.0,         // mm = starker Regen
        rainPenaltyBike: 8,
        rainPenaltyWalk: 5,
        windStrong: 30,         // km/h
        windPenaltyBike: 3,
        coldBelow: 3,           // °C
        hotAbove: 35,           // °C
        tempPenalty: 3,
        bikeSpeedKmh: 14,       // nur Schätzmodus (ohne ORS)
        walkSpeedKmh: 4.8,      // nur Schätzmodus
        detourFactor: 1.3,      // Luftlinie -> Straßenweg (Schätzmodus, Fußwege zur Station)
        maxWalkToStationM: 1000,// weiter als das bis zur nächsten Station -> BiciMAD nicht sinnvoll
        transitSpeedKmh: 18,    // ÖPNV-Schätzung: mittlere Reisegeschwindigkeit
        transitAccessMin: 8,    // Fußwege zur und von der Haltestelle
        transitWaitMin: 4,      // mittlere Wartezeit
        staleMin: 15,           // BiciMAD-Daten älter als das = veraltet
        weatherStaleMin: 30,    // Wetterdaten älter als das = veraltet
        maxRoutesPerUser: 3
    }
};
global.set('cfg', cfg);
node.status({
    fill: cfg.apis.orsKey ? 'green' : 'yellow', shape: 'dot',
    text: cfg.apis.orsKey ? 'ORS-Schlüssel gesetzt' : 'kein ORS-Schlüssel: Schätzmodus'
});
